"""Bind a saved native review candidate to qualified, immutable native part exports."""
import argparse,datetime,gzip,hashlib,json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(name):return json.loads((ROOT/name).read_text())
def evidence(name):
 p=ROOT/name
 return {'path':name,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
parser=argparse.ArgumentParser();parser.add_argument('--view',choices=['high','cached','bounded'],default='high');args=parser.parse_args();kind={'high':'review','cached':'display','bounded':'bounded-display'}[args.view];export=read('audits/current-native-whole-'+kind+'-export.json');assert export['passed']
version=export['saved_master_version'];model_path=f'exports/whole-native-master-{version}/native-whole-{kind}-candidate.json.gz'
raw=gzip.decompress((ROOT/model_path).read_bytes());assert hashlib.sha256(raw).hexdigest()==export['model_sha256'];model=json.loads(raw)
mapping=read('manifests/whole-native-component-map-candidate.json')['parts'];by_id={v['component_part_number']:(k,v)for k,v in mapping.items()};assert len(by_id)==88
index=read('audits/current-definition-evidence-index.json');assert index['geometry_lineage_complete']and index['geometry_lineage_covered_count']==88
index_by={r['part']:r for r in index['parts']};instances=read('audits/current-master-assembly-refresh.json')['instances'];parts={}
for p in model['parts']:
 if p['native_definition_id']not in by_id:continue
 source_key,base=by_id[p['native_definition_id']];step=ROOT/base['native_step'];assert hashlib.sha256(step.read_bytes()).hexdigest()==base['native_step_sha256'];subsystem=instances[p['name']]['subsystem'];record={**base,'native_definition_id':p['native_definition_id'],'definition_key':source_key,'saved_document':subsystem,'saved_version':export['subsystem_versions'][subsystem],'review_source_mesh_key':p['source_mesh_key'],'export_provenance':{'kind':'Retained qualified native STEP export; not represented as a fresh export of the latest checkpoint.','comparison_and_original_export_evidence':index_by[source_key],'current_equivalence_binding':['audits/current-native-leg-saved-reopen.json'if subsystem=='leg'else'audits/whole-current-body-target-reconciliation.json','audits/current-definition-evidence-index.json','audits/current-native-master-saved-reopen.json']}}
 if p['mesh']in parts:assert parts[p['mesh']]==record
 parts[p['mesh']]=record
assert len({p['native_definition_id']for p in parts.values()})==88
reports=['audits/current-definition-evidence-index.json','audits/current-native-pose-edit-restore.json','audits/current-native-leg-saved-reopen.json','audits/current-master-assembly-refresh.json','audits/current-native-master-saved-reopen.json','audits/current-native-cleanup-history-inventory.json','audits/removed-obsolete-pose-joints.json','audits/current-whole-rail-retessellation-binding.json','audits/current-outer-native-section-resolution.json','manifests/whole-reference-display-roles.json','manifests/whole-purchased-reference-groups.json']
record={'native_source_of_truth':False,'full_robot_native_source_of_truth':False,'status':'saved_native_candidate_pending_independent_browser_motion_review','scope':'Current low-profile Tinfox baseline only. Fastener-reduction redesign and optional raised-head variant are not included.','saved_master_version':version,'subsystem_versions':export['subsystem_versions'],'review_model':model_path,'review_model_sha256':export['model_sha256'],'review_model_gzip_sha256':export['sha256'],'parts':parts,'unique_native_custom_and_stock_definitions':88,'inventory':model['inventory'],'source_target_sha256':export['source_target_sha256'],'required_remaining_gates':['Independent current native browser/mesh and motion-parity review.','Explicit scope approval and canonical review metadata.'],'evidence':[evidence(p)for p in reports],'qualification_limits':['Existing fixed body contacts and combined joint-range contacts remain inherited prototype limitations.','Physical strength, material fits, CNC access where unreviewed, cable routing and loaded locomotion remain unqualified.','Default Fusion materials do not establish mass; review mass remains unestimated.','The optical backing is provisional; protective glazing and seals remain unmodeled.'],'updated_utc':datetime.datetime.now(datetime.UTC).isoformat()}
record['view_kind']=kind;record['native_high_detail_export']=evidence('audits/current-native-whole-review-export.json');record['exact_geometry_scope']='Display tessellation is separate from exact native BRep and manufacturing-export tolerances.';path=ROOT/('manifests/current-whole-native-exports-candidate.json'if args.view=='high'else'manifests/current-whole-native-'+kind+'-candidate.json');path.write_text(json.dumps(record,indent=2)+'\n');print({'manifest':str(path),'mesh_export_entries':len(parts),'unique_definitions':88,'saved_master_version':version})
